SOURCE = {
    "id": "jenechka-editorial", "name": "Jenechka modern vocabulary and corrections",
    "url": "https://github.com/mengusabah/jenechka-cards", "license": "MIT",
    "licenseUrl": "https://github.com/mengusabah/jenechka-cards/blob/main/LICENSE",
    "attribution": "Jenechka Cards contributors; original model-assisted editorial translations and corrections.",
    "methodology": "Original everyday vocabulary with one defined meaning per row and translations in all thirteen languages. Model-assisted editorial additions and repairs are distinguished from dictionary-attested alternatives. No proprietary learning-app vocabulary was used; independent native-speaker certification is not claimed.",
    "version": "editorial-2026-10-20-1",
}

# Independent editorial judgments for the native expressions and their exact
# academic senses, rather than borrowing an English vocabulary-list level.
# Transparent native compounds and familiar school-discussion terms can be
# C1 even when the specialist loanword in another language is placed at C2.
LEVEL_ADJUSTMENTS = {
    "advanced-ontology": {"tr": "C1", "ja": "C1"},
    "advanced-utilitarianism": {"tr": "C1", "es": "C1", "fr": "C1", "it": "C1", "pt": "C1"},
    "advanced-metonymy": {"tr": "C1"},
    "advanced-polysemy": {"tr": "C1", "es": "C1", "fr": "C1", "it": "C1", "pt": "C1",
                         "zh": "C1", "ja": "C1", "ko": "C1"},
    "advanced-existentialism": {"en": "C1", "tr": "C1", "de": "C1", "fr": "C1", "es": "C1",
                              "it": "C1", "ru": "C1", "pt": "C1", "nl": "C1", "ar": "C1"},
    "advanced-determinism": {"en": "C1", "fr": "C1", "es": "C1", "it": "C1", "pt": "C1", "zh": "C1", "ar": "C1"},
    "advanced-relativism": {"en": "C1", "fr": "C1", "es": "C1", "it": "C1", "pt": "C1"},
}


def build():
    concepts = []
    for key, topics, pos, meaning, translations in ROWS:
        forms = translations.split("|")
        assert len(forms) == len(CODES), key
        concepts.append({
            "id": "editorial-" + key, "meaning": meaning, "pos": pos,
            "categories": topics.split(), "sourceUrl": SOURCE["url"],
            "forms": {code: {"text": text, "tags": [], **(
                {"estimatedLevel": "A1"} if key.startswith("core-") else
                {"estimatedLevel": LEVEL_ADJUSTMENTS.get(key, {}).get(code, "C2")} if key.startswith("advanced-") else {}
            )} for code, text in zip(CODES, forms)},
            "frequencyPriority": key.startswith("core-"),
            "evidence": {"headword": forms[0], "partOfSpeech": pos, "translationSense": meaning,
                         "source": SOURCE["id"], "method": "original-editorial-translation"},
        })
    return {"sources": [SOURCE], "categories": [], "concepts": concepts}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = Path(__file__).resolve().parent.parent / "vocabulary/source-data/editorial.json"
    text = json.dumps(build(), ensure_ascii=False, indent=2) + "\n"
    if args.check:
        assert output.read_text() == text, "Stale editorial vocabulary"
    else:
        output.write_text(text)
    print(f"{len(ROWS)} modern concepts × {len(CODES)} languages.")
